import{_ as s,C as r,c as l,o as i,a3 as a,G as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Tags","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/tags.md","filePath":"master/human-resources/employees/setup/tags.md","lastUpdated":1791902625000}'),n={name:"master/human-resources/employees/setup/tags.md"};function p(g,e,d,h,m,c){const t=r("ImagePopup");return i(),l("div",null,[e[0]||(e[0]=a('<h1 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h1><p>A tag is a short coloured label you attach to an employee, such as Senior, Sales or Operations. An employee can carry many tags. Tags help you spot groups of people at a glance on the employee cards.</p><blockquote><p><strong>In simple words:</strong> A tag is a sticker you put on an employee.</p></blockquote><p>Open <code>Employees → Configurations → Tags</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. The sample data has 14 tags: Sales, Trainer, Employee, Consultant, Management, HR, Engineering, Finance, Operations, Marketing, Support, Senior, Junior and Full-time.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has no tabs. Columns are <strong>Name</strong> and <strong>Color</strong>. The colour shows as a small swatch. Use the search box to find a tag.</p>',7)),o(t,{src:"/images1/employees/set_tags_list.png",alt:"Tags list with the Name and Color columns showing tags such as Operations and Senior"}),e[1]||(e[1]=a('<h2 id="create-a-tag" tabindex="-1">Create a tag <a class="header-anchor" href="#create-a-tag" aria-label="Permalink to &quot;Create a tag&quot;">​</a></h2><p>This example adds <strong>Night Shift</strong>.</p><ol><li>Open <code>Employees → Configurations → Tags</code>.</li><li>Click <strong>New Tag</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Night Shift</code>.</li><li><strong><em>Color:</em></strong> Optional. Type a hex code such as <code>#6366f1</code>, or pick a colour with the picker.</li></ul>',4)),o(t,{src:"/images1/employees/set_tags_form.png",alt:"Create Tags window filled with Night Shift and the colour code #6366f1"}),e[2]||(e[2]=a('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also create a tag from the employee form. Click the plus button next to <strong>Employee Tags</strong>.</p></div><h2 id="where-tags-are-used" tabindex="-1">Where tags are used <a class="header-anchor" href="#where-tags-are-used" aria-label="Permalink to &quot;Where tags are used&quot;">​</a></h2><ul><li>The <strong>Employee Tags</strong> field on the employee form takes one or more tags.</li><li>Tags show as coloured badges on the employee card in the list.</li><li>You can group the employee list by <strong>Tags</strong>.</li><li>On the department Employees page, the cards show the same badges.</li></ul><h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to rename a tag or change its colour. Click <strong>Delete</strong> to remove it.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../employees/add-employee.html">Add an employee</a></li><li><a href="./../employees/employee-list.html">Employee list</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./">Setup overview</a></li></ul>',8))])}const T=s(n,[["render",p]]);export{_ as __pageData,T as default};
